def midpointChainThresholdFile(head, k):
    a=head
    out=[]
    slow=fast=a
    while fast and fast.next:
        slow=slow.next
        fast=fast.next.next
    node=slow
    while node:
        out.append(node.val)
        node=node.next
    return sum(x>=k for x in out)

